import { useEffect, useMemo, useState } from "react";
import { useAuth } from "@/_core/hooks/useAuth";
import { trpc } from "@/lib/trpc";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Sheet, SheetContent, SheetHeader, SheetTitle } from "@/components/ui/sheet";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { AlertTriangle, Bell, Building2, CalendarDays, Camera, CheckCircle2, ChevronRight, ClipboardList, ClipboardPenLine, Clock3, Filter, ImagePlus, LayoutDashboard, MapPin, Menu, PackageOpen, Plus, QrCode, Search, Settings2, ShieldCheck, Sparkles, Users2, Wrench, X } from "lucide-react";
import { cn } from "@/lib/utils";

const statusOrder = ["OPEN", "ASSIGNED", "IN_PROGRESS", "COMPLETED", "CLOSED"] as const;
const fallbackOrders: any[] = [];
const fallbackพื้นที่s: any[] = [];
const fallbackTechs: any[] = [];

const statusColor: Record<string, string> = { OPEN: "bg-sky-50 text-sky-700 border-sky-200", ASSIGNED: "bg-violet-50 text-violet-700 border-violet-200", IN_PROGRESS: "bg-amber-50 text-amber-700 border-amber-200", COMPLETED: "bg-emerald-50 text-emerald-700 border-emerald-200", CLOSED: "bg-slate-100 text-slate-600 border-slate-200" };
const priorityColor: Record<string, string> = { URGENT: "text-rose-700 bg-rose-50", HIGH: "text-orange-700 bg-orange-50", MEDIUM: "text-amber-700 bg-amber-50", LOW: "text-slate-600 bg-slate-100" };

function formatDate(value: unknown) { return value ? new Date(value as string).toLocaleDateString("th-TH", { day: "2-digit", month: "short" }) : "—"; }
function initials(name: string) { return name.split(" ").map(part => part[0]).join("").slice(0, 2).toUpperCase(); }

export function LegacyHome() {
  const [section, setSection] = useState("Overview");
  const [search, setSearch] = useState("");
  const [status, setStatus] = useState("ALL");
  const [priority, setPriority] = useState("ALL");
  const [category, setCategory] = useState("ALL");
  const [locationFilter, setLocationFilter] = useState("ALL");
  const [fromDate, setFromDate] = useState("");
  const [toDate, setToDate] = useState("");
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [createOpen, setCreateOpen] = useState(false);
  const [mobileNav, setMobileNav] = useState(false);
  const [notificationsOpen, setNotificationsOpen] = useState(false);
  const { user: authUser, loading: authLoading, refresh: refreshAuth } = useAuth();
  const [authCheckTimedOut, setAuthCheckTimedOut] = useState(false);
  useEffect(() => {
    if (!authLoading) {
      setAuthCheckTimedOut(false);
      return;
    }
    const timer = window.setTimeout(() => setAuthCheckTimedOut(true), 7000);
    return () => window.clearTimeout(timer);
  }, [authLoading]);
  const isSystemAdmin = authUser?.role === "ADMIN";
  const statsQuery = trpc.dashboard.stats.useQuery();
  const ordersQuery = trpc.workOrders.list.useQuery({ search: search || undefined, status: status === "ALL" ? undefined : status, priority: priority === "ALL" ? undefined : priority, category: category === "ALL" ? undefined : category, location: locationFilter === "ALL" ? undefined : locationFilter, from: fromDate ? new Date(`${fromDate}T00:00:00`) : undefined, to: toDate ? new Date(`${toDate}T23:59:59`) : undefined });
  const locationsQuery = trpc.locations.list.useQuery();
  const techniciansQuery = trpc.technicians.list.useQuery();
  const partsQuery = trpc.parts.list.useQuery();
  const partIssuesQuery = trpc.partIssues.list.useQuery();
  const detailQuery = trpc.workOrders.detail.useQuery({ woId: selectedId ?? "" }, { enabled: Boolean(selectedId) });
  const createMutation = trpc.workOrders.create.useMutation({ onSuccess: () => { setCreateOpen(false); ordersQuery.refetch(); statsQuery.refetch(); } });
  const updateMutation = trpc.workOrders.update.useMutation({ onSuccess: () => { setSelectedId(null); ordersQuery.refetch(); statsQuery.refetch(); } });
  const assignMutation = trpc.workOrders.assign.useMutation({ onSuccess: () => { ordersQuery.refetch(); statsQuery.refetch(); techniciansQuery.refetch(); detailQuery.refetch(); } });
  const statusMutation = trpc.workOrders.changeStatus.useMutation({ onSuccess: () => { ordersQuery.refetch(); statsQuery.refetch(); techniciansQuery.refetch(); detailQuery.refetch(); notificationsQuery.refetch(); }, onError: error => window.alert(error.message === "AFTER_PHOTO_REQUIRED" ? "กรุณาเพิ่มรูปหลังเสร็จงานอย่างน้อย 1 รูปก่อนทำเครื่องหมายว่าเสร็จ" : `ไม่สามารถเปลี่ยนสถานะได้: ${error.message}`) });
  const uploadMutation = trpc.workOrders.uploadAttachment.useMutation({ onSuccess: () => detailQuery.refetch() });
  const notificationsQuery = trpc.notifications.list.useQuery({ userId: authUser?.openId }, { enabled: Boolean(authUser) });
  const markNotificationReadMutation = trpc.notifications.markRead.useMutation({ onSuccess: () => notificationsQuery.refetch() });
  const profileQuery = trpc.profile.me.useQuery(undefined, { enabled: Boolean(authUser) });
  const completeProfileMutation = trpc.profile.completeRegistration.useMutation({ onSuccess: () => profileQuery.refetch() });

  const orders = (ordersQuery.data ?? []) as typeof fallbackOrders;
  const locations = locationsQuery.data ?? [];
  const technicians = techniciansQuery.data ?? [];
  const parts = partsQuery.data ?? [];
  const partIssues = partIssuesQuery.data ?? [];
  const counts = useMemo(() => statusOrder.reduce<Record<string, number>>((acc, key) => { acc[key] = orders.filter(order => order.statusCode === key).length; return acc; }, {}), [orders]);
  const filteredOrders = useMemo(() => orders.filter(order => `${order.woId} ${order.description} ${order.locationId} ${order.categoryCode}`.toLowerCase().includes(search.toLowerCase()) && (status === "ALL" || order.statusCode === status) && (priority === "ALL" || order.priorityCode === priority) && (category === "ALL" || order.categoryCode === category) && (locationFilter === "ALL" || order.locationId === locationFilter)), [orders, search, status, priority]);
  const selected = selectedId ? orders.find(order => order.woId === selectedId) : null;
  const dashboardLoading = statsQuery.isLoading || ordersQuery.isLoading || locationsQuery.isLoading || techniciansQuery.isLoading;
  const dataError = statsQuery.error || ordersQuery.error || locationsQuery.error || techniciansQuery.error;

  function uploadAttachment(event: React.ChangeEvent<HTMLInputElement>, attachmentType: "BEFORE" | "AFTER" | "OTHER" = "OTHER") {
    const file = event.target.files?.[0];
    if (!file || !selected) return;
    const reader = new FileReader();
    reader.onload = () => { if (typeof reader.result === "string" && authUser) uploadMutation.mutate({ woId: selected.woId, attachmentType, fileName: file.name, mimeType: file.type || "application/octet-stream", fileDataBase64: reader.result, uploadedBy: authUser.openId }); };
    reader.readAsDataURL(file);
  }

  const navItems = [
    { value: "Overview", label: "ภาพรวม", icon: LayoutDashboard }, { value: "Work Orders", label: "ใบงาน", icon: ClipboardList, count: orders.length }, { value: "Parts", label: "อะไหล่", icon: PackageOpen, count: parts.length }, { value: "Part Issues", label: "รายการเบิกอะไหล่", icon: ClipboardPenLine, count: partIssues.length }, { value: "Locations", label: "พื้นที่", icon: MapPin }, { value: "Technicians", label: "ช่าง", icon: Wrench }, ...(isSystemAdmin ? [{ value: "Users", label: "ผู้ใช้งาน", icon: Users2 }] : []), { value: "Settings", label: "ตั้งค่า", icon: Settings2 },
  ];

  function submitCreate(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const data = new FormData(event.currentTarget);
    createMutation.mutate({ locationId: String(data.get("locationId")), categoryCode: String(data.get("categoryCode")), priorityCode: String(data.get("priorityCode")), description: String(data.get("description")), subCategory: String(data.get("subCategory") || ""), sourceChannel: "WEBAPP", customerVisible: false });
  }

  function submitRegistration(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const data = new FormData(event.currentTarget);
    completeProfileMutation.mutate({ displayName: String(data.get("displayName") || ""), department: String(data.get("department") || "") });
  }

  if (authLoading && !authCheckTimedOut) return <AuthShell><p className="text-sm text-slate-600">กำลังตรวจสอบการเข้าสู่ระบบ...</p></AuthShell>;
  if (authLoading && authCheckTimedOut) return <AuthRecoveryScreen onRetry={() => { setAuthCheckTimedOut(false); void refreshAuth(); }} />;
  if (!authUser) return <LineLoginScreen />;
  if (profileQuery.isLoading) return <AuthShell><p className="text-sm text-slate-600">กำลังเตรียมข้อมูลผู้ใช้งาน...</p></AuthShell>;
  if (profileQuery.data?.needsRegistration) return <RegistrationScreen defaultName={authUser.name ?? ""} isPending={completeProfileMutation.isPending} error={completeProfileMutation.error?.message} onSubmit={submitRegistration} />;

  return (
    <div className="min-h-screen bg-[radial-gradient(circle_at_top_right,_rgba(14,107,98,0.12),_transparent_34%),linear-gradient(135deg,_#eef7f5_0%,_#f8fafc_48%,_#f4efe5_100%)] text-slate-900">
      <aside className={cn("fixed inset-y-0 left-0 z-40 flex w-[260px] flex-col overflow-y-auto border-r border-slate-200 bg-white px-5 py-6 transition-transform lg:translate-x-0", mobileNav ? "translate-x-0" : "-translate-x-full")}>
        <div className="flex items-center justify-between px-2"><div className="flex items-center gap-3"><div className="flex h-10 w-10 items-center justify-center rounded-2xl bg-[#0e6b62] text-white shadow-lg shadow-teal-900/15"><Wrench className="h-5 w-5" /></div><div><p className="text-[10px] font-bold uppercase tracking-[0.22em] text-teal-700">NORTHSTAR</p><p className="text-sm font-semibold text-slate-900">ศูนย์งานซ่อมบำรุง</p></div></div><button className="lg:hidden" onClick={() => setMobileNav(false)}><X className="h-5 w-5" /></button></div>
        <div className="mt-10 flex-1"><p className="px-3 text-[10px] font-bold uppercase tracking-[0.2em] text-slate-400">พื้นที่ปฏิบัติงาน</p><nav className="mt-3 space-y-1">{navItems.map(item => <button key={item.label} onClick={() => { setSection(item.value); setMobileNav(false); }} className={cn("flex w-full items-center justify-between rounded-xl px-3 py-3 text-sm transition", section === item.value ? "bg-teal-50 font-semibold text-[#0e6b62]" : "text-slate-500 hover:bg-slate-50 hover:text-slate-800")}><span className="flex items-center gap-3"><item.icon className="h-[18px] w-[18px]" />{item.label}</span>{item.count ? <span className="rounded-full bg-slate-100 px-2 py-0.5 text-[11px] font-semibold text-slate-500">{item.count}</span> : null}</button>)}</nav></div>
        <div className="mt-8 rounded-2xl bg-[#0e6b62] p-4 text-white"><div className="mb-5 flex items-center justify-between"><span className="text-xs font-medium text-teal-100">สุขภาพ SLA</span><ShieldCheck className="h-4 w-4 text-teal-200" /></div><div className="flex items-end justify-between"><div><p className="text-2xl font-semibold">ออนไลน์</p><p className="mt-1 text-[11px] text-teal-100">คำนวณจากวันครบกำหนด</p></div><div className="h-12 w-12 rounded-full border-[5px] border-teal-300/40 border-t-white" /></div></div>
        <div className="mt-5 flex items-center gap-3 rounded-2xl border border-slate-100 bg-slate-50 p-3"><div className="flex h-9 w-9 items-center justify-center rounded-full bg-amber-100 text-xs font-bold text-amber-800">{initials(profileQuery.data?.profile?.displayName ?? authUser.name ?? "ผู้")}</div><div className="min-w-0 flex-1"><p className="truncate text-xs font-semibold">{profileQuery.data?.profile?.displayName ?? authUser.name}</p><p className="text-[10px] text-slate-400">{profileQuery.data?.profile?.department ?? "ผู้ใช้งาน"}</p></div><ChevronRight className="h-4 w-4 text-slate-400" /></div>
      </aside>
      {mobileNav && <button className="fixed inset-0 z-30 bg-slate-950/20 lg:hidden" onClick={() => setMobileNav(false)} aria-label="ปิด navigation" />}
      <main className="lg:pl-[260px]">
        <header className="sticky top-0 z-20 border-b border-slate-200/80 bg-[#eef7f5]/85 px-4 backdrop-blur-xl sm:px-8"><div className="mx-auto flex h-16 w-full max-w-[1120px] items-center justify-between gap-2 sm:h-[76px] sm:gap-3"> <div className="flex items-center gap-3"><button className="rounded-lg p-2 hover:bg-white lg:hidden" onClick={() => setMobileNav(true)}><Menu className="h-5 w-5" /></button><div><p className="text-xs font-medium text-slate-400">ศูนย์ปฏิบัติการงานซ่อมบำรุง</p><h1 className="mt-0.5 text-lg font-semibold tracking-tight sm:text-xl">สวัสดี {profileQuery.data?.profile?.displayName ?? authUser.name} <span className="text-amber-500">✦</span></h1></div></div><div className="flex items-center gap-2 sm:gap-4"><div className="hidden items-center gap-2 rounded-xl border border-slate-200 bg-white/85 px-3 py-2 shadow-sm sm:flex"><Search className="h-4 w-4 text-slate-400" /><input value={search} onChange={event => setSearch(event.target.value)} className="w-32 bg-transparent text-xs outline-none placeholder:text-slate-400" placeholder="ค้นหาใบงาน..." /></div><button onClick={() => setNotificationsOpen(true)} className="relative rounded-xl border border-slate-200 bg-white p-2.5 text-slate-500"><Bell className="h-4 w-4" />{(notificationsQuery.data?.filter(item => !item.isRead).length ?? 0) > 0 && <span className="absolute right-2 top-2 h-1.5 w-1.5 rounded-full bg-rose-500" />}</button><div className="hidden h-9 w-9 items-center justify-center rounded-full bg-slate-800 text-xs font-bold text-white sm:flex">{initials(profileQuery.data?.profile?.displayName ?? authUser.name ?? "ผู้")}</div></div></div></header>
        <div className="mx-auto w-full max-w-[1120px] px-4 py-5 sm:px-8 sm:py-7 lg:px-10">
          {(section === "Overview" || section === "Work Orders") && <div className="mb-4 flex items-center gap-2 rounded-xl border border-teal-100 bg-teal-50/70 px-3 py-2.5 text-xs text-teal-800 sm:mb-5"><Users2 className="h-4 w-4 shrink-0 text-teal-700" /><span>ใบงานใหม่จะระบุผู้แจ้งเป็น <strong>{profileQuery.data?.profile?.displayName ?? authUser.name}</strong> จากบัญชี LINE ที่เข้าสู่ระบบ</span></div>}
          <div className="mb-5 flex flex-col justify-between gap-4 sm:mb-7 md:flex-row md:items-end"><div><div className="mb-2 flex items-center gap-2 text-xs font-medium text-teal-700"><span className="h-2 w-2 rounded-full bg-emerald-500" /> {section === "Users" ? "การจัดการสิทธิ์และการเข้าถึงระบบ" : "ภาพรวมการปฏิบัติงานแบบสด"}</div><h2 className="text-2xl font-semibold tracking-tight text-slate-900 sm:text-3xl">{section === "Overview" ? "ภาพรวมงานซ่อมบำรุง" : section === "Work Orders" ? "ใบงาน" : section === "Parts" ? "อะไหล่" : section === "Part Issues" ? "รายการเบิกอะไหล่" : section === "Locations" ? "พื้นที่" : section === "Technicians" ? "ช่าง" : section === "Users" ? "ผู้ใช้งาน" : "ตั้งค่า"}</h2><p className="mt-2 max-w-xl text-sm leading-6 text-slate-500">{section === "Users" ? "จัดการชื่อ แผนก บทบาท และสถานะการใช้งานของบัญชีที่เข้าสู่ระบบด้วย LINE" : "ศูนย์ควบคุมงานซ่อมบำรุงสำหรับความพร้อมของห้องพัก ใบงานที่กำลังดำเนินการ และกำลังคนของโรงแรม"}</p></div>{section !== "Users" && <Button onClick={() => setCreateOpen(true)} className="h-10 w-full rounded-xl bg-[#0e6b62] px-4 text-sm shadow-lg shadow-teal-900/10 hover:bg-[#09554e] md:h-11 md:w-auto md:px-5"><Plus className="mr-2 h-4 w-4" /> สร้างใบงาน</Button>}</div>
          {section === "Users" ? <AdminUsersWorkspace currentUserId={authUser.openId} /> : section === "Settings" ? <AdminSettingsWorkspace /> : section === "Parts" ? <PartsWorkspace parts={parts} /> : section === "Part Issues" ? <PartIssuesWorkspace issues={partIssues} /> : section === "Overview" || section === "Work Orders" ? <>
            <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard label="ใบงานทั้งหมด" value={String(statsQuery.data?.total || orders.length).padStart(2, "0")} meta="จำนวนจากฐานข้อมูลปัจจุบัน" icon={ClipboardList} accent="teal" /><StatCard label="เปิดและกำลังดำเนินการ" value={String((counts.OPEN ?? 0) + (counts.ASSIGNED ?? 0) + (counts.IN_PROGRESS ?? 0)).padStart(2, "0")} meta="ต้องติดตาม" icon={Clock3} accent="amber" /><StatCard label="เกิน SLA" value={String(statsQuery.data?.overdue ?? 0).padStart(2, "0")} meta="ห้องที่ต้องเร่งตรวจสอบ" icon={ShieldCheck} accent="rose" /><StatCard label="เสร็จวันนี้" value={String(statsQuery.data?.today ?? 0).padStart(2, "0")} meta="ความพร้อมสำหรับผู้เข้าพัก" icon={CheckCircle2} accent="emerald" /></div>
            <div className="mt-5 grid gap-4 sm:mt-6 sm:gap-6 xl:grid-cols-[1.6fr_1fr]"><Card className="rounded-2xl border-slate-200/70 shadow-sm"><CardHeader className="flex flex-row items-center justify-between pb-4"><div><CardTitle className="text-base font-semibold">ภาพรวมสถานะใบงาน</CardTitle><p className="mt-1 text-xs text-slate-400">ปริมาณงานแยกตามสถานะ</p></div><button className="rounded-lg border border-slate-200 p-2 text-slate-500 hover:bg-slate-50"><Filter className="h-4 w-4" /></button></CardHeader><CardContent><div className="flex h-[210px] items-end gap-3 border-b border-l border-slate-100 px-3 pb-0 pt-7">{statusOrder.map((item, index) => { const value = counts[item] ?? 0; const max = Math.max(...Object.values(counts), 1); return <div key={item} className="flex h-full flex-1 flex-col items-center justify-end gap-2"><span className="text-xs font-semibold text-slate-700">{value}</span><div className={cn("w-full max-w-[52px] rounded-t-xl transition-all", index === 2 ? "bg-[#0e6b62]" : "bg-teal-100")} style={{ height: `${Math.max(value / max * 72, 15)}%` }} /><span className="mb-3 text-center text-[10px] font-medium text-slate-400">{item.replace("_", " ")}</span></div>; })}</div><div className="mt-5 flex flex-wrap gap-x-6 gap-y-2 text-xs text-slate-500"><span><b className="mr-1 text-slate-800">{statsQuery.data?.week ?? 0}</b> สร้างในสัปดาห์นี้</span><span className="text-slate-400">ตัวชี้วัด SLA คำนวณจากเวลาของใบงานจริง</span></div></CardContent></Card><Card className="rounded-2xl border-slate-200/70 shadow-sm"><CardHeader className="pb-4"><CardTitle className="text-base font-semibold">สัดส่วนสถานะ</CardTitle><p className="mt-1 text-xs text-slate-400">รวมทุกพื้นที่ที่ใช้งาน</p></CardHeader><CardContent><div className="flex flex-col items-center gap-6 sm:flex-row sm:gap-7"><div className="relative flex h-28 w-28 shrink-0 sm:h-32 sm:w-32 items-center justify-center rounded-full" style={{ background: `conic-gradient(#0e6b62 0 35%, #f59e0b 35% 55%, #8b5cf6 55% 72%, #10b981 72% 88%, #cbd5e1 88% 100%)` }}><div className="flex h-20 w-20 flex-col items-center justify-center rounded-full bg-white"><span className="text-2xl font-semibold">{orders.length}</span><span className="text-[10px] text-slate-400">ทั้งหมด</span></div></div><div className="min-w-0 flex-1 space-y-3">{statusOrder.map((item, index) => <div key={item} className="flex items-center justify-between gap-2 text-xs"><span className="flex items-center gap-2 text-slate-500"><i className={cn("h-2 w-2 rounded-full", ["bg-sky-400", "bg-violet-500", "bg-amber-400", "bg-emerald-500", "bg-slate-300"][index])} />{item}</span><b className="text-slate-800">{counts[item] ?? 0}</b></div>)}</div></div></CardContent></Card></div>
            <Card className="mt-6 rounded-2xl border-slate-200/70 shadow-sm"><CardHeader className="flex flex-col gap-4 pb-3 sm:flex-row sm:items-center sm:justify-between"><div><CardTitle className="text-base font-semibold">ใบงานล่าสุด</CardTitle><p className="mt-1 text-xs text-slate-400">ติดตาม มอบหมาย และปิดงานแจ้งซ่อม</p></div><div className="grid grid-cols-2 gap-2 sm:flex sm:flex-wrap"><div className="col-span-2 flex min-h-10 items-center gap-2 rounded-lg border border-slate-200 bg-white px-3 py-2 sm:hidden"><Search className="h-4 w-4 text-slate-400" /><input value={search} onChange={event => setSearch(event.target.value)} className="min-w-0 flex-1 bg-transparent text-xs outline-none" placeholder="ค้นหาในรายการใบงาน..." /></div><select value={status} onChange={event => setStatus(event.target.value)} className="h-10 min-w-0 rounded-lg border border-slate-200 bg-white px-2 text-[11px] text-slate-600 outline-none sm:h-9 sm:text-xs"><option value="ALL">ทุกสถานะ</option>{statusOrder.map(item => <option key={item}>{item}</option>)}</select><select value={category} onChange={event => setCategory(event.target.value)} className="h-10 min-w-0 rounded-lg border border-slate-200 bg-white px-2 text-[11px] text-slate-600 outline-none sm:h-9 sm:text-xs"><option value="ALL">ทุกหมวดหมู่</option><option>PLUMBING</option><option>ELECTRICAL</option><option>HVAC</option><option>EQUIPMENT</option><option>SAFETY</option><option>CIVIL</option></select><select value={locationFilter} onChange={event => setLocationFilter(event.target.value)} className="h-10 min-w-0 rounded-lg border border-slate-200 bg-white px-2 text-[11px] text-slate-600 outline-none sm:h-9 sm:text-xs"><option value="ALL">ทุกพื้นที่</option>{locations.map(location => <option key={location.locationId} value={location.locationId}>{location.areaName}</option>)}</select><input type="date" value={fromDate} onChange={event => setFromDate(event.target.value)} className="h-10 min-w-0 rounded-lg border border-slate-200 bg-white px-2 text-[11px] text-slate-600 outline-none sm:h-9 sm:text-xs" aria-label="From date" /><input type="date" value={toDate} onChange={event => setToDate(event.target.value)} className="h-10 min-w-0 rounded-lg border border-slate-200 bg-white px-2 text-[11px] text-slate-600 outline-none sm:h-9 sm:text-xs" aria-label="To date" /><select value={priority} onChange={event => setPriority(event.target.value)} className="h-10 min-w-0 rounded-lg border border-slate-200 bg-white px-2 text-[11px] text-slate-600 outline-none sm:h-9 sm:text-xs"><option value="ALL">ทุกระดับความสำคัญ</option><option>URGENT</option><option>HIGH</option><option>MEDIUM</option><option>LOW</option></select></div></CardHeader><CardContent className="px-0">{dashboardLoading && <div className="mx-6 mb-4 rounded-xl border border-teal-100 bg-teal-50 px-4 py-3 text-xs font-medium text-teal-800">กำลังโหลดข้อมูลการปฏิบัติงาน...</div>}{dataError && <div className="mx-6 mb-4 rounded-xl border border-rose-100 bg-rose-50 px-4 py-3 text-xs font-medium text-rose-800">ไม่สามารถโหลดข้อมูลได้ กรุณารีเฟรชแล้วลองใหม่</div>}<div className="hidden overflow-x-auto sm:block"><table className="w-full min-w-[760px] text-left text-sm"><thead><tr className="border-y border-slate-100 bg-slate-50/60 text-[10px] font-bold uppercase tracking-[0.14em] text-slate-400"><th className="px-6 py-3">ใบงาน</th><th className="px-4 py-3">พื้นที่</th><th className="px-4 py-3">ความสำคัญ</th><th className="px-4 py-3">สถานะ</th><th className="px-4 py-3">ผู้รับผิดชอบ</th><th className="px-6 py-3 text-right">ครบกำหนด</th></tr></thead><tbody>{filteredOrders.map(order => <tr key={order.woId} onClick={() => setSelectedId(order.woId)} className="cursor-pointer border-b border-slate-50 transition hover:bg-teal-50/30"><td className="px-6 py-4"><div className="flex items-center gap-3"><div className="flex h-9 w-9 items-center justify-center rounded-xl bg-slate-100 text-slate-500"><ClipboardList className="h-4 w-4" /></div><div><p className="font-semibold text-slate-800">{order.woId}</p><p className="mt-0.5 max-w-[250px] truncate text-xs text-slate-400">{order.description}</p></div></div></td><td className="px-4 py-4"><div className="flex items-center gap-2 text-xs text-slate-600"><MapPin className="h-3.5 w-3.5 text-slate-400" />{locations.find(location => location.locationId === order.locationId)?.areaName ?? order.locationId}</div><p className="mt-1 pl-5 text-[10px] text-slate-400">{order.categoryCode}</p></td><td className="px-4 py-4"><span className={cn("rounded-md px-2 py-1 text-[10px] font-bold", priorityColor[order.priorityCode] ?? priorityColor.LOW)}>{order.priorityCode}</span></td><td className="px-4 py-4"><span className={cn("inline-flex rounded-full border px-2.5 py-1 text-[10px] font-bold", statusColor[order.statusCode])}>{order.statusCode}</span></td><td className="px-4 py-4"><div className="flex items-center gap-2 text-xs text-slate-600">{order.assignedTechId ? <><span className="flex h-7 w-7 items-center justify-center rounded-full bg-teal-100 text-[9px] font-bold text-teal-800">{initials(technicians.find(tech => tech.techId === order.assignedTechId)?.techName ?? order.assignedTechId)}</span>{technicians.find(tech => tech.techId === order.assignedTechId)?.techName ?? order.assignedTechId}</> : <span className="text-slate-400">ยังไม่มอบหมาย</span>}</div></td><td className="px-6 py-4 text-right text-xs font-medium text-slate-500">{formatDate(order.dueAt)}</td></tr>)}</tbody></table></div><div className="space-y-2 px-4 pb-4 sm:hidden">{filteredOrders.map(order => <button type="button" key={`mobile-${order.woId}`} onClick={() => setSelectedId(order.woId)} className="w-full rounded-xl border border-slate-100 bg-white p-3 text-left shadow-sm transition active:scale-[0.99] hover:border-teal-200"><div className="flex items-start justify-between gap-3"><div className="min-w-0"><div className="flex items-center gap-2"><ClipboardList className="h-3.5 w-3.5 shrink-0 text-slate-400" /><p className="truncate text-xs font-bold text-slate-800">{order.woId}</p></div><p className="mt-1 line-clamp-2 text-xs leading-5 text-slate-500">{order.description}</p></div><span className={cn("shrink-0 rounded-full border px-2 py-1 text-[10px] font-bold", statusColor[order.statusCode])}>{order.statusCode}</span></div><div className="mt-3 flex flex-wrap items-center gap-x-3 gap-y-1 text-[10px] text-slate-500"><span className="inline-flex items-center gap-1"><MapPin className="h-3 w-3 text-slate-400" />{locations.find(location => location.locationId === order.locationId)?.areaName ?? order.locationId}</span><span className={cn("rounded-md px-1.5 py-0.5 font-bold", priorityColor[order.priorityCode] ?? priorityColor.LOW)}>{order.priorityCode}</span><span className="ml-auto">ครบกำหนด {formatDate(order.dueAt)}</span></div></button>)}</div>{filteredOrders.length === 0 && <div className="p-8 text-center text-sm text-slate-400">ไม่พบใบงานตามตัวกรองที่เลือก</div>}</CardContent></Card>
          </> : <SectionPlaceholder section={section} locations={locations} technicians={technicians} onCreate={() => setCreateOpen(true)} />}
        </div>
      </main>
      <Dialog open={notificationsOpen} onOpenChange={setNotificationsOpen}><DialogContent className="max-h-[85vh] w-[calc(100%-2rem)] max-w-md overflow-y-auto rounded-2xl p-4 sm:p-6"><DialogHeader><DialogTitle>การแจ้งเตือน</DialogTitle></DialogHeader><div className="max-h-[420px] space-y-2 overflow-y-auto">{(notificationsQuery.data ?? []).length === 0 ? <p className="rounded-xl bg-slate-50 p-4 text-sm text-slate-500">ยังไม่มีการแจ้งเตือนสำหรับผู้ใช้นี้</p> : (notificationsQuery.data ?? []).map((notification: any) => <button key={notification.notificationId} onClick={() => !notification.isRead && markNotificationReadMutation.mutate({ notificationId: notification.notificationId })} className={cn("w-full min-h-10 rounded-xl border p-3 text-left transition hover:bg-slate-50", notification.isRead ? "border-slate-100 bg-white" : "border-teal-100 bg-teal-50/40")}><div className="flex items-center justify-between gap-3"><span className="text-xs font-bold text-slate-700">{notification.title}</span><span className="text-[10px] text-slate-400">{formatDate(notification.createdAt)}</span></div><p className="mt-1 text-xs leading-5 text-slate-500">{notification.message}</p></button>)}</div></DialogContent></Dialog><Dialog open={Boolean(selectedId)} onOpenChange={งานที่เปิด => !งานที่เปิด && setSelectedId(null)}><DialogContent className="max-h-[90vh] w-[calc(100%-2rem)] max-w-2xl overflow-y-auto rounded-2xl p-4 sm:p-6"><DialogHeader><DialogTitle className="flex items-center gap-3"><span>{selected?.woId}</span>{selected && <span className={cn("rounded-full border px-2.5 py-1 text-[10px]", statusColor[selected.statusCode])}>{selected.statusCode}</span>}</DialogTitle></DialogHeader>{selected && <div className="space-y-4 sm:space-y-6">{detailQuery.isLoading && <div className="rounded-xl border border-teal-100 bg-teal-50 px-4 py-3 text-xs font-medium text-teal-800">กำลังโหลดประวัติสถานะ...</div>}{detailQuery.error && <div className="rounded-xl border border-rose-100 bg-rose-50 px-4 py-3 text-xs font-medium text-rose-800">ไม่สามารถโหลดประวัติสถานะของใบงานนี้</div>}<div className="grid gap-3 sm:grid-cols-3"><DetailItem label="พื้นที่" value={locations.find(location => location.locationId === selected.locationId)?.areaName ?? selected.locationId} /><DetailItem label="หมวดหมู่" value={selected.categoryCode} /><DetailItem label="ความสำคัญ" value={selected.priorityCode} /></div><div className="rounded-xl bg-slate-50 p-4"><p className="text-[10px] font-bold uppercase tracking-[0.15em] text-slate-400">รายละเอียด</p><p className="mt-2 text-sm leading-6 text-slate-700">{selected.description}</p></div><form onSubmit={event => { event.preventDefault(); const data = new FormData(event.currentTarget); assignMutation.mutate({ woId: selected.woId, techId: String(data.get("techId") || "") || null, assignedTeam: String(data.get("assignedTeam") || "") || null, actorUserId: "USR-0003", comment: "ปรับการมอบหมายงานจาก Work Order detail" }); }} className="rounded-xl border border-violet-100 bg-violet-50/50 p-4"><p className="text-xs font-bold uppercase tracking-[0.15em] text-violet-700">การมอบหมายงาน</p><div className="mt-3 grid gap-3 sm:grid-cols-[1fr_150px_auto]"><select name="techId" defaultValue={selected.assignedTechId ?? ""} className="h-10 rounded-lg border border-slate-200 bg-white px-3 text-sm"><option value="">ยังไม่มอบหมาย</option>{technicians.map(tech => <option key={tech.techId} value={tech.techId}>{tech.techName} · {tech.currentOpenJobs}/{tech.maxOpenJobs}</option>)}</select><Input name="assignedTeam" defaultValue={selected.assignedTeam ?? ""} placeholder="ทีม" className="min-h-10 bg-white" /><Button type="submit" disabled={assignMutation.isPending} className="min-h-10 rounded-lg bg-violet-700 hover:bg-violet-800">{assignMutation.isPending ? "กำลังมอบหมาย..." : "มอบหมาย"}</Button></div><p className="mt-2 text-[11px] text-violet-700/80">เฉพาะ SUPERVISOR และ ADMIN ที่มอบหมายงานได้ ระบบจะตรวจสอบความจุงานของช่างที่เซิร์ฟเวอร์</p></form><form onSubmit={event => { event.preventDefault(); const data = new FormData(event.currentTarget); updateMutation.mutate({ woId: selected.woId, values: { description: String(data.get("description")), priorityCode: String(data.get("priorityCode")) } }); }} className="rounded-xl border border-teal-100 bg-teal-50/50 p-4"><p className="text-xs font-bold uppercase tracking-[0.15em] text-teal-700">แก้ไขด่วน</p><div className="mt-3 grid gap-3 sm:grid-cols-[1fr_150px]"><Input name="description" defaultValue={selected.description} className="bg-white" aria-label="รายละเอียด" /><select name="priorityCode" defaultValue={selected.priorityCode} className="h-10 rounded-lg border border-slate-200 bg-white px-3 text-sm"><option>LOW</option><option>MEDIUM</option><option>HIGH</option><option>URGENT</option></select></div><Button type="submit" disabled={updateMutation.isPending} className="mt-3 min-h-10 rounded-lg bg-[#0e6b62]">{updateMutation.isPending ? "กำลังบันทึก..." : "บันทึกการเปลี่ยนแปลง"}</Button></form><div className="flex flex-wrap gap-2">{selected.statusCode === "ASSIGNED" && <Button size="sm" onClick={() => statusMutation.mutate({ woId: selected.woId, fromStatus: "ASSIGNED", toStatus: "IN_PROGRESS", actorUserId: "USR-0003", comment: "เริ่มดำเนินการซ่อม" })} disabled={statusMutation.isPending} className="min-h-10 rounded-lg bg-amber-600 hover:bg-amber-700">เริ่มงาน</Button>}{selected.statusCode === "IN_PROGRESS" && <Button size="sm" onClick={() => statusMutation.mutate({ woId: selected.woId, fromStatus: "IN_PROGRESS", toStatus: "COMPLETED", actorUserId: "USR-0003", comment: "ดำเนินการซ่อมเสร็จแล้ว" })} disabled={statusMutation.isPending} className="min-h-10 rounded-lg bg-emerald-700 hover:bg-emerald-800">ทำเครื่องหมายว่าเสร็จ</Button>}{selected.statusCode === "COMPLETED" && <Button size="sm" onClick={() => statusMutation.mutate({ woId: selected.woId, fromStatus: "COMPLETED", toStatus: "CLOSED", actorUserId: "USR-0003", comment: "ตรวจรับและปิดใบงาน" })} disabled={statusMutation.isPending} className="min-h-10 rounded-lg bg-slate-800 hover:bg-slate-900">ปิดใบงาน</Button>}</div><div className="mt-4 rounded-xl border border-slate-100 bg-white p-4"><p className="text-xs font-semibold text-slate-700">ไฟล์แนบ</p><div className="mt-3 flex flex-wrap items-center gap-3"><label className="inline-flex min-h-10 cursor-pointer items-center rounded-lg border border-dashed border-teal-300 px-3 py-2 text-xs font-semibold text-teal-700 hover:bg-teal-50"><input type="file" className="hidden" onChange={uploadAttachment} accept="image/*,.pdf,.doc,.docx" />{uploadMutation.isPending ? "กำลังอัปโหลด..." : "อัปโหลดรูปภาพ / เอกสาร"}</label>{(detailQuery.data?.attachments ?? []).map((file: any) => <a key={file.attachmentId} href={file.fileUrl} target="_blank" rel="noreferrer" className="rounded-lg bg-slate-50 px-3 py-2 text-xs text-slate-600 hover:bg-slate-100">{file.fileName}</a>)}</div></div><div><div className="mb-4 flex items-center justify-between"><p className="text-sm font-semibold">สถานะ log</p><span className="text-xs text-slate-400">{detailQuery.data?.logs?.length ?? 3} เหตุการณ์</span></div><div className="space-y-4">{(detailQuery.data?.logs ?? []).map((log: any, index: number) => <div key={log.logId} className="flex gap-3"><div className="flex flex-col items-center"><div className={cn("h-3 w-3 rounded-full", index === 0 ? "bg-teal-600 ring-4 ring-teal-50" : "bg-slate-300")} />{index < 2 && <div className="h-full w-px bg-slate-200" />}</div><div className="-mt-1 pb-2"><div className="flex items-center gap-2"><span className="text-xs font-bold text-slate-700">{log.toStatus}</span><span className="text-[10px] text-slate-400">{formatDate(log.changedAt)}</span></div><p className="mt-1 text-xs text-slate-500">{log.comment}</p></div></div>)}</div></div><div className="flex justify-end gap-2 border-t border-slate-100 pt-4"><Button variant="outline" className="min-h-10 rounded-xl" onClick={() => setSelectedId(null)}>ปิด</Button><Button className="min-h-10 rounded-xl bg-[#0e6b62]">เปิดรายละเอียดเต็ม <ChevronRight className="ml-1 h-4 w-4" /></Button></div></div>}</DialogContent></Dialog>
      <Sheet open={createOpen} onOpenChange={setCreateOpen}><SheetContent className="w-full overflow-y-auto sm:max-w-xl"><SheetHeader><SheetTitle className="text-xl">สร้างใบงาน</SheetTitle><p className="text-sm text-slate-500">บันทึกคำขอแจ้งซ่อมใหม่สำหรับโรงแรม</p></SheetHeader><form onSubmit={submitCreate} className="mt-8 space-y-5"><div className="grid gap-5 sm:grid-cols-2"><label className="space-y-2 text-xs font-semibold text-slate-600">พื้นที่<select name="locationId" required className="mt-2 h-11 w-full rounded-xl border border-slate-200 bg-white px-3 text-sm font-normal outline-none focus:border-teal-500">{locations.map(location => <option key={location.locationId} value={location.locationId}>{location.areaName}</option>)}</select></label><label className="space-y-2 text-xs font-semibold text-slate-600">หมวดหมู่<select name="categoryCode" required className="mt-2 h-11 w-full rounded-xl border border-slate-200 bg-white px-3 text-sm font-normal outline-none focus:border-teal-500"><option>PLUMBING</option><option>ELECTRICAL</option><option>HVAC</option><option>EQUIPMENT</option><option>SAFETY</option><option>CIVIL</option></select></label></div><div className="grid gap-5 sm:grid-cols-2"><label className="space-y-2 text-xs font-semibold text-slate-600">ความสำคัญ<select name="priorityCode" required className="mt-2 h-11 w-full rounded-xl border border-slate-200 bg-white px-3 text-sm font-normal outline-none focus:border-teal-500"><option>MEDIUM</option><option>LOW</option><option>HIGH</option><option>URGENT</option></select></label><label className="space-y-2 text-xs font-semibold text-slate-600">หมวดย่อย<Input name="subCategory" placeholder="เช่น ท่อน้ำทิ้งฝักบัว" className="mt-2 h-11 rounded-xl" /></label></div><label className="space-y-2 text-xs font-semibold text-slate-600">รายละเอียดปัญหา<Textarea name="description" required placeholder="อธิบายปัญหา ผลกระทบ และข้อมูลที่ช่วยให้ช่างทำงานได้เร็วขึ้น..." className="mt-2 min-h-32 rounded-xl" /></label><div className="rounded-xl border border-dashed border-teal-200 bg-teal-50/50 p-4 text-xs text-teal-800"><div className="flex items-center gap-2 font-semibold"><Sparkles className="h-4 w-4" /> ระบบจัดลำดับงานพร้อมใช้งาน</div><p className="mt-1 leading-5 text-teal-700/80">ระบบจะกำหนด SLA ตามหมวดหมู่และระดับความสำคัญ จากนั้นหัวหน้างานสามารถมอบหมายช่างที่เหมาะสมได้</p></div><Button type="submit" disabled={createMutation.isPending} className="h-11 w-full rounded-xl bg-[#0e6b62]">{createMutation.isPending ? "กำลังสร้าง..." : "สร้างใบงาน"}</Button></form></SheetContent></Sheet>
    </div>
  );
}

function StatCard({ label, value, meta, icon: Icon, accent }: { label: string; value: string; meta: string; icon: any; accent: string }) { const colors: Record<string, string> = { teal: "bg-teal-50 text-teal-700", amber: "bg-amber-50 text-amber-700", rose: "bg-rose-50 text-rose-700", emerald: "bg-emerald-50 text-emerald-700" }; return <Card className="rounded-2xl border-slate-200/70 shadow-sm"><CardContent className="p-4 sm:p-5"><div className="flex items-start justify-between"><div><p className="text-xs font-medium text-slate-400">{label}</p><p className="mt-2 text-2xl font-semibold tracking-tight text-slate-900 sm:mt-3 sm:text-3xl">{value}</p><p className="mt-2 text-[11px] font-medium text-slate-400">{meta}</p></div><div className={cn("rounded-xl p-2.5", colors[accent])}><Icon className="h-4 w-4" /></div></div></CardContent></Card>; }
function DetailItem({ label, value }: { label: string; value: string }) { return <div className="rounded-xl border border-slate-100 p-3"><p className="text-[10px] font-bold uppercase tracking-[0.15em] text-slate-400">{label}</p><p className="mt-2 truncate text-sm font-semibold text-slate-700">{value}</p></div>; }
function PartsWorkspace({ parts }: { parts: any[] }) {
  const lowStock = parts.filter(part => Number(part.availableQty) < Number(part.minStockQty));
  return <div className="space-y-5">
    <div className="grid gap-4 sm:grid-cols-3"><StatCard label="อะไหล่ทั้งหมด" value={String(parts.length).padStart(2, "0")} meta="จากชีต 10_Parts" icon={PackageOpen} accent="teal" /><StatCard label="ใกล้หมด / ต่ำกว่าขั้นต่ำ" value={String(lowStock.length).padStart(2, "0")} meta="ควรตรวจสอบการสั่งซื้อ" icon={AlertTriangle} accent="rose" /><StatCard label="มูลค่าคงคลังโดยประมาณ" value={parts.reduce((sum, part) => sum + Number(part.currentStockQty) * Number(part.unitCostThb), 0).toLocaleString("th-TH")} meta="บาท" icon={ClipboardList} accent="amber" /></div>
    <Card className="overflow-hidden rounded-2xl border-slate-200/70 shadow-sm"><CardHeader><CardTitle className="text-base font-semibold">คลังอะไหล่</CardTitle><p className="mt-1 text-xs text-slate-400">ข้อมูลล่าสุดจากชีต 10_Parts · คงเหลือพร้อมใช้ = คงคลัง − จอง</p></CardHeader><CardContent className="p-0"><div className="overflow-x-auto"><table className="w-full min-w-[860px] text-left text-sm"><thead><tr className="border-y border-slate-100 bg-slate-50/80 text-[10px] font-bold tracking-wide text-slate-400"><th className="px-5 py-3">รหัส / ชื่ออะไหล่</th><th className="px-4 py-3">หมวด</th><th className="px-4 py-3">ที่เก็บ</th><th className="px-4 py-3 text-right">คงคลัง</th><th className="px-4 py-3 text-right">พร้อมใช้</th><th className="px-4 py-3 text-right">ต้นทุน/หน่วย</th></tr></thead><tbody>{parts.map(part => { const isLow = Number(part.availableQty) < Number(part.minStockQty); return <tr key={part.partId} className="border-b border-slate-50 hover:bg-teal-50/30"><td className="px-5 py-4"><p className="font-semibold text-slate-800">{part.partNameTh}</p><p className="mt-1 text-xs text-slate-400">{part.partId} · {part.partCode}</p></td><td className="px-4 py-4 text-xs text-slate-600">{part.categoryCode}</td><td className="px-4 py-4 text-xs text-slate-600">{part.storageLocation ?? "—"}</td><td className="px-4 py-4 text-right text-xs font-semibold text-slate-700">{part.currentStockQty} {part.unit}</td><td className={cn("px-4 py-4 text-right text-xs font-bold", isLow ? "text-rose-700" : "text-emerald-700")}>{part.availableQty} {part.unit}{isLow && <span className="ml-1 text-[10px]">ต่ำ</span>}</td><td className="px-4 py-4 text-right text-xs text-slate-600">฿{Number(part.unitCostThb).toLocaleString("th-TH")}</td></tr>; })}</tbody></table></div></CardContent></Card>
  </div>;
}

function PartIssuesWorkspace({ issues }: { issues: any[] }) {
  const statusLabel: Record<string, string> = { REQUESTED: "รออนุมัติ", APPROVED: "อนุมัติแล้ว", ISSUED: "เบิกจ่ายแล้ว" };
  return <Card className="overflow-hidden rounded-2xl border-slate-200/70 shadow-sm"><CardHeader><CardTitle className="text-base font-semibold">รายการเบิกอะไหล่</CardTitle><p className="mt-1 text-xs text-slate-400">ข้อมูลล่าสุดจากชีต 11_Part_Issues · เชื่อมโยงกับใบงานและพื้นที่ใช้งาน</p></CardHeader><CardContent className="p-0"><div className="overflow-x-auto"><table className="w-full min-w-[920px] text-left text-sm"><thead><tr className="border-y border-slate-100 bg-slate-50/80 text-[10px] font-bold tracking-wide text-slate-400"><th className="px-5 py-3">รายการ / ใบงาน</th><th className="px-4 py-3">อะไหล่</th><th className="px-4 py-3 text-right">ขอเบิก</th><th className="px-4 py-3 text-right">อนุมัติ</th><th className="px-4 py-3 text-right">จ่ายจริง</th><th className="px-4 py-3">สถานะ</th><th className="px-4 py-3 text-right">ค่าใช้จ่าย</th></tr></thead><tbody>{issues.map(issue => <tr key={issue.issueId} className="border-b border-slate-50 hover:bg-teal-50/30"><td className="px-5 py-4"><p className="font-semibold text-slate-800">{issue.issueId}</p><p className="mt-1 text-xs text-slate-400">{issue.woId} · {issue.usedAtLocationId ?? "ไม่ระบุพื้นที่"}</p></td><td className="px-4 py-4"><p className="text-xs font-semibold text-slate-700">{issue.partNameTh}</p><p className="mt-1 text-[10px] text-slate-400">{issue.partCode}</p></td><td className="px-4 py-4 text-right text-xs text-slate-600">{issue.qtyRequested} {issue.unit}</td><td className="px-4 py-4 text-right text-xs text-slate-600">{issue.qtyApproved} {issue.unit}</td><td className="px-4 py-4 text-right text-xs font-semibold text-slate-700">{issue.qtyIssued} {issue.unit}</td><td className="px-4 py-4"><span className={cn("rounded-full border px-2.5 py-1 text-[10px] font-bold", issue.issueStatus === "ISSUED" ? "border-emerald-200 bg-emerald-50 text-emerald-700" : issue.issueStatus === "APPROVED" ? "border-violet-200 bg-violet-50 text-violet-700" : "border-amber-200 bg-amber-50 text-amber-700")}>{statusLabel[issue.issueStatus] ?? issue.issueStatus}</span></td><td className="px-4 py-4 text-right text-xs font-semibold text-slate-700">฿{Number(issue.issueCostThb).toLocaleString("th-TH")}</td></tr>)}</tbody></table></div></CardContent></Card>;
}

function AdminUsersWorkspace({ currentUserId }: { currentUserId: string }) {
  const { user } = useAuth();
  const utils = trpc.useUtils();
  const isAdmin = user?.role === "ADMIN";
  const [search, setSearch] = useState("");
  const usersListInput = useMemo(() => ({ search: search.trim() || undefined }), [search]);
  const usersQuery = trpc.users.list.useQuery(usersListInput, { enabled: isAdmin });
  const [editing, setEditing] = useState<any | null>(null);
  const [feedback, setFeedback] = useState<string | null>(null);
  const updateMutation = trpc.users.update.useMutation({
    onSuccess: async () => {
      setEditing(null);
      setFeedback("บันทึกข้อมูลผู้ใช้งานเรียบร้อยแล้ว");
      await utils.users.list.invalidate();
    },
    onError: error => setFeedback(`บันทึกไม่สำเร็จ: ${error.message}`),
  });
  const users = (usersQuery.data ?? []) as any[];
  const filteredUsers = users;
  const roleLabel: Record<string, string> = { GUEST: "ผู้แจ้งงาน", STAFF: "พนักงาน", SUPERVISOR: "หัวหน้างาน", TECH: "ช่าง", ADMIN: "ผู้ดูแล" };
  const activeCount = users.filter(item => item.isActive).length;
  const adminCount = users.filter(item => item.roleCode === "ADMIN").length;
  const formatLogin = (value: unknown) => value ? new Date(value as string).toLocaleString("th-TH", { dateStyle: "medium", timeStyle: "short" }) : "ยังไม่เคยเข้าใช้";

  if (!isAdmin) return <Card className="rounded-2xl border-amber-200 bg-amber-50/80 shadow-sm"><CardContent className="p-6 sm:p-8"><div className="flex gap-3"><AlertTriangle className="mt-0.5 h-5 w-5 shrink-0 text-amber-700" /><div><h3 className="font-semibold text-amber-900">จำกัดสิทธิ์สำหรับผู้ดูแลระบบ</h3><p className="mt-1 text-sm leading-6 text-amber-800">การจัดการบัญชีผู้ใช้เป็นข้อมูลด้านสิทธิ์การเข้าถึง จึงเปิดให้เฉพาะบทบาท ADMIN</p></div></div></CardContent></Card>;

  return <div className="space-y-5">
    <div className="grid gap-4 sm:grid-cols-3"><StatCard label="ผู้ใช้งานทั้งหมด" value={String(users.length).padStart(2, "0")} meta="บัญชีที่ลงทะเบียนด้วย LINE" icon={Users2} accent="teal" /><StatCard label="บัญชีที่เปิดใช้งาน" value={String(activeCount).padStart(2, "0")} meta="เข้าใช้และสร้างใบงานได้" icon={CheckCircle2} accent="emerald" /><StatCard label="ผู้ดูแลระบบ" value={String(adminCount).padStart(2, "0")} meta="มีสิทธิ์จัดการระบบ" icon={ShieldCheck} accent="amber" /></div>
    <Card className="overflow-hidden rounded-2xl border-slate-200/70 bg-white/90 shadow-sm"><CardHeader className="gap-4 border-b border-slate-100 pb-5 sm:flex-row sm:items-center sm:justify-between"><div><CardTitle className="text-base font-semibold">บัญชีผู้ใช้งาน</CardTitle><p className="mt-1 text-xs leading-5 text-slate-400">ข้อมูลจะสร้างหลังผู้ใช้เข้าสู่ระบบและกรอกชื่อกับแผนกในครั้งแรก</p></div><div className="flex min-h-10 w-full items-center gap-2 rounded-xl border border-slate-200 bg-slate-50 px-3 sm:w-72"><Search className="h-4 w-4 shrink-0 text-slate-400" /><input value={search} onChange={event => setSearch(event.target.value)} className="min-w-0 flex-1 bg-transparent text-xs outline-none placeholder:text-slate-400" placeholder="ค้นหาชื่อ แผนก หรือ LINE ID" /></div></CardHeader>
      <CardContent className="p-0">
        {feedback && <div className={cn("mx-4 mt-4 rounded-xl px-4 py-3 text-sm sm:mx-6", feedback.startsWith("บันทึกไม่สำเร็จ") ? "bg-rose-50 text-rose-700" : "bg-emerald-50 text-emerald-700")}>{feedback}</div>}
        {usersQuery.isLoading && <div className="p-6 text-sm text-slate-500">กำลังโหลดข้อมูลผู้ใช้งาน...</div>}
        {usersQuery.error && <div className="m-4 rounded-xl bg-rose-50 p-4 text-sm text-rose-700 sm:m-6">ไม่สามารถโหลดข้อมูลผู้ใช้งานได้: {usersQuery.error.message}</div>}
        {!usersQuery.isLoading && !usersQuery.error && filteredUsers.length === 0 && <div className="p-8 text-center text-sm text-slate-500">ยังไม่พบผู้ใช้งานตามคำค้นหา</div>}
        {!usersQuery.isLoading && !usersQuery.error && filteredUsers.length > 0 && <><div className="hidden overflow-x-auto sm:block"><table className="w-full min-w-[840px] text-left text-sm"><thead><tr className="border-y border-slate-100 bg-slate-50/70 text-[10px] font-bold uppercase tracking-[0.12em] text-slate-400"><th className="px-6 py-3">ผู้ใช้งาน</th><th className="px-4 py-3">แผนก</th><th className="px-4 py-3">บทบาท</th><th className="px-4 py-3">สถานะ</th><th className="px-4 py-3">เข้าใช้ล่าสุด</th><th className="px-6 py-3 text-right">จัดการ</th></tr></thead><tbody>{filteredUsers.map(item => <tr key={item.userId} className="border-b border-slate-50 transition hover:bg-teal-50/30"><td className="px-6 py-4"><div className="flex items-center gap-3">{item.pictureUrl ? <img src={item.pictureUrl} alt="" className="h-9 w-9 rounded-full object-cover" /> : <div className="flex h-9 w-9 items-center justify-center rounded-full bg-teal-100 text-xs font-bold text-teal-700">{initials(item.displayName)}</div>}<div className="min-w-0"><p className="truncate font-semibold text-slate-800">{item.displayName}</p><p className="mt-0.5 truncate text-[11px] text-slate-400">LINE: {item.lineUserId ?? item.userId}</p></div></div></td><td className="px-4 py-4 text-xs text-slate-600">{item.department ?? "ไม่ระบุ"}</td><td className="px-4 py-4"><span className="rounded-full bg-violet-50 px-2.5 py-1 text-[10px] font-bold text-violet-700">{roleLabel[item.roleCode] ?? item.roleCode}</span></td><td className="px-4 py-4"><span className={cn("rounded-full px-2.5 py-1 text-[10px] font-bold", item.isActive ? "bg-emerald-50 text-emerald-700" : "bg-slate-100 text-slate-500")}>{item.isActive ? "ใช้งาน" : "ระงับ"}</span></td><td className="px-4 py-4 text-xs text-slate-500">{formatLogin(item.lastLoginAt)}</td><td className="px-6 py-4 text-right"><Button variant="outline" size="sm" onClick={() => { setEditing({ ...item }); setFeedback(null); }} className="h-9 rounded-lg border-slate-200 bg-white text-xs text-slate-700 hover:bg-teal-50">แก้ไข</Button></td></tr>)}</tbody></table></div><div className="space-y-3 p-4 sm:hidden">{filteredUsers.map(item => <div key={item.userId} className="rounded-xl border border-slate-200 bg-white p-4 shadow-sm"><div className="flex items-start gap-3">{item.pictureUrl ? <img src={item.pictureUrl} alt="" className="h-10 w-10 rounded-full object-cover" /> : <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-teal-100 text-xs font-bold text-teal-700">{initials(item.displayName)}</div>}<div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold text-slate-800">{item.displayName}</p><p className="mt-0.5 truncate text-[11px] text-slate-400">{item.department ?? "ไม่ระบุแผนก"} · {roleLabel[item.roleCode] ?? item.roleCode}</p></div><span className={cn("rounded-full px-2 py-1 text-[10px] font-bold", item.isActive ? "bg-emerald-50 text-emerald-700" : "bg-slate-100 text-slate-500")}>{item.isActive ? "ใช้งาน" : "ระงับ"}</span></div><div className="mt-3 flex items-center justify-between gap-3 border-t border-slate-100 pt-3"><p className="text-[11px] text-slate-400">{formatLogin(item.lastLoginAt)}</p><Button variant="outline" size="sm" onClick={() => { setEditing({ ...item }); setFeedback(null); }} className="h-9 rounded-lg border-slate-200 bg-white text-xs">แก้ไข</Button></div></div>)}</div></>}
      </CardContent>
    </Card>
    <Dialog open={Boolean(editing)} onOpenChange={open => { if (!open && !updateMutation.isPending) setEditing(null); }}><DialogContent className="max-h-[92vh] w-[calc(100vw-2rem)] overflow-y-auto rounded-2xl p-5 sm:max-w-lg sm:p-6"><DialogHeader><DialogTitle>แก้ไขผู้ใช้งาน</DialogTitle><p className="text-sm leading-6 text-slate-500">ปรับข้อมูล แผนก บทบาท และสถานะการเข้าใช้งานได้จากหน้าจอนี้</p></DialogHeader>{editing && <form className="mt-5 space-y-4" onSubmit={event => { event.preventDefault(); updateMutation.mutate({ userId: editing.userId, values: { displayName: String(editing.displayName ?? "").trim(), department: String(editing.department ?? "").trim() || null, roleCode: editing.roleCode, isActive: Boolean(editing.isActive), notes: String(editing.notes ?? "").trim() || null } }); }}><div className="flex items-center gap-3 rounded-xl bg-slate-50 p-3">{editing.pictureUrl ? <img src={editing.pictureUrl} alt="" className="h-10 w-10 rounded-full object-cover" /> : <div className="flex h-10 w-10 items-center justify-center rounded-full bg-teal-100 text-xs font-bold text-teal-700">{initials(editing.displayName)}</div>}<div className="min-w-0"><p className="truncate text-sm font-semibold text-slate-800">LINE: {editing.lineUserId ?? editing.userId}</p><p className="mt-0.5 text-[11px] text-slate-400">เข้าใช้ล่าสุด {formatLogin(editing.lastLoginAt)}</p></div></div><label className="block space-y-2 text-sm font-medium text-slate-700">ชื่อที่แสดง<Input required value={editing.displayName ?? ""} onChange={event => setEditing({ ...editing, displayName: event.target.value })} className="h-11 rounded-xl" /></label><label className="block space-y-2 text-sm font-medium text-slate-700">แผนก<Input value={editing.department ?? ""} onChange={event => setEditing({ ...editing, department: event.target.value })} placeholder="เช่น แผนกแม่บ้าน" className="h-11 rounded-xl" /></label><div className="grid gap-4 sm:grid-cols-2"><label className="block space-y-2 text-sm font-medium text-slate-700">บทบาท<select value={editing.roleCode} disabled={editing.userId === currentUserId} onChange={event => setEditing({ ...editing, roleCode: event.target.value })} className="h-11 w-full rounded-xl border border-slate-200 bg-white px-3 text-sm font-normal outline-none disabled:cursor-not-allowed disabled:bg-slate-100">{["GUEST", "STAFF", "SUPERVISOR", "TECH", "ADMIN"].map(role => <option key={role} value={role}>{roleLabel[role]} ({role})</option>)}</select></label><label className="flex min-h-11 items-end gap-3 pb-1 text-sm font-medium text-slate-700"><input type="checkbox" checked={Boolean(editing.isActive)} disabled={editing.userId === currentUserId} onChange={event => setEditing({ ...editing, isActive: event.target.checked })} className="h-4 w-4 rounded border-slate-300 text-teal-700" /><span>เปิดให้ใช้งานบัญชี</span></label></div>{editing.userId === currentUserId && <p className="rounded-lg bg-amber-50 px-3 py-2 text-xs leading-5 text-amber-800">เพื่อความปลอดภัย ระบบไม่อนุญาตให้ผู้ดูแลลดสิทธิ์หรือระงับบัญชีของตนเอง</p>}<label className="block space-y-2 text-sm font-medium text-slate-700">บันทึกภายใน<Textarea value={editing.notes ?? ""} onChange={event => setEditing({ ...editing, notes: event.target.value })} placeholder="ข้อมูลที่ผู้ดูแลต้องการบันทึกเพิ่มเติม" className="min-h-24 rounded-xl" /></label><div className="flex flex-col-reverse gap-3 pt-2 sm:flex-row sm:justify-end"><Button type="button" variant="outline" onClick={() => setEditing(null)} disabled={updateMutation.isPending} className="h-11 rounded-xl">ยกเลิก</Button><Button type="submit" disabled={updateMutation.isPending} className="h-11 rounded-xl bg-[#0e6b62] hover:bg-[#09554e]">{updateMutation.isPending ? "กำลังบันทึก..." : "บันทึกการเปลี่ยนแปลง"}</Button></div></form>}</DialogContent></Dialog>
  </div>;
}

function AdminSettingsWorkspace() {
  const { user } = useAuth();
  const utils = trpc.useUtils();
  const isAdmin = user?.role === "ADMIN";
  const settingsQuery = trpc.integrations.line.settings.useQuery(undefined, { enabled: isAdmin });
  const [channelAccessToken, setChannelAccessToken] = useState("");
  const [recipientId, setRecipientId] = useState("");
  const [isEnabled, setIsEnabled] = useState(false);
  const [alertUrgent, setAlertUrgent] = useState(true);
  const [alertOverdue, setAlertOverdue] = useState(true);
  const [feedback, setFeedback] = useState<string | null>(null);

  useEffect(() => {
    if (!settingsQuery.data) return;
    setIsEnabled(settingsQuery.data.isEnabled);
    setAlertUrgent(settingsQuery.data.alertUrgent);
    setAlertOverdue(settingsQuery.data.alertOverdue);
  }, [settingsQuery.data]);

  const saveMutation = trpc.integrations.line.save.useMutation({
    onSuccess: async () => {
      setChannelAccessToken("");
      setRecipientId("");
      setFeedback("บันทึกการตั้งค่า LINE เรียบร้อยแล้ว");
      await utils.integrations.line.settings.invalidate();
    },
    onError: error => setFeedback(error.message),
  });
  const testMutation = trpc.integrations.line.test.useMutation({
    onSuccess: async () => {
      setFeedback("ส่งข้อความทดสอบไปยัง LINE เรียบร้อยแล้ว");
      await utils.integrations.line.settings.invalidate();
    },
    onError: error => setFeedback(`ทดสอบไม่สำเร็จ: ${error.message}`),
  });

  if (!isAdmin) return <Card className="rounded-2xl border-amber-200 bg-amber-50/80 shadow-sm"><CardContent className="p-6 sm:p-8"><div className="flex gap-3"><AlertTriangle className="mt-0.5 h-5 w-5 shrink-0 text-amber-700" /><div><h3 className="font-semibold text-amber-900">จำกัดสิทธิ์สำหรับผู้ดูแลระบบ</h3><p className="mt-1 text-sm leading-6 text-amber-800">การตั้งค่า LINE Messaging API จัดการได้เฉพาะบทบาท ADMIN เพื่อปกป้องข้อมูลการเชื่อมต่อ</p></div></div></CardContent></Card>;

  const settings = settingsQuery.data;
  const canTest = Boolean(settings?.configured || (channelAccessToken.trim() && recipientId.trim()));
  return <div className="grid gap-5 xl:grid-cols-[minmax(0,1.35fr)_minmax(280px,0.65fr)]">
    <Card className="rounded-2xl border-slate-200/80 bg-white/90 shadow-sm"><CardHeader className="border-b border-slate-100 pb-5"><div className="flex items-start gap-3"><div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-emerald-50 text-emerald-700"><Bell className="h-5 w-5" /></div><div><CardTitle className="text-base font-semibold text-slate-900">LINE Messaging API</CardTitle><p className="mt-1 text-xs leading-5 text-slate-500">ส่งแจ้งเตือนงานเร่งด่วนและงานเกิน SLA ไปยัง LINE Official Account</p></div></div></CardHeader><CardContent className="p-5 sm:p-6"><form className="space-y-5" onSubmit={event => { event.preventDefault(); setFeedback(null); saveMutation.mutate({ channelAccessToken: channelAccessToken || undefined, recipientId: recipientId || undefined, isEnabled, alertUrgent, alertOverdue }); }}>
      <div className="grid gap-4 sm:grid-cols-2"><label className="space-y-2 text-sm font-medium text-slate-700"><span>Channel Access Token</span><Input type="password" value={channelAccessToken} onChange={event => setChannelAccessToken(event.target.value)} placeholder={settings?.tokenMasked ?? "ใส่ token จาก LINE Developers"} autoComplete="new-password" className="h-11 rounded-xl" /><span className="block text-[11px] font-normal leading-5 text-slate-400">{settings?.tokenMasked ? `ตั้งค่าไว้แล้ว: ${settings.tokenMasked}` : "ระบบจะเข้ารหัสก่อนบันทึก และไม่แสดง token จริงอีกครั้ง"}</span></label>
      <label className="space-y-2 text-sm font-medium text-slate-700"><span>User ID หรือ Group ID</span><Input value={recipientId} onChange={event => setRecipientId(event.target.value)} placeholder={settings?.recipientMasked ?? "Uxxxxxxxx หรือ Cxxxxxxxx"} autoComplete="off" className="h-11 rounded-xl" /><span className="block text-[11px] font-normal leading-5 text-slate-400">{settings?.recipientMasked ? `ตั้งค่าไว้แล้ว: ${settings.recipientMasked}` : "ใช้ปลายทางที่จะรับข้อความแจ้งเตือน"}</span></label></div>
      <div className="space-y-3 rounded-xl border border-slate-200 bg-slate-50/70 p-4"><ToggleRow label="เปิดใช้งานการแจ้งเตือน LINE" description="เริ่มส่งข้อความหลังจากบันทึก token และปลายทางครบ" checked={isEnabled} onChange={setIsEnabled} /><ToggleRow label="แจ้งเตือนงานเร่งด่วน" description="ส่งเมื่อมีใบงานที่ตั้งความสำคัญเป็น URGENT, P1 หรือ CRITICAL" checked={alertUrgent} onChange={setAlertUrgent} /><ToggleRow label="แจ้งเตือนงานเกิน SLA" description="ส่งเมื่อระบบพบใบงานที่เลยเวลาครบกำหนด" checked={alertOverdue} onChange={setAlertOverdue} /></div>
      {feedback && <div className={cn("rounded-xl px-4 py-3 text-sm", feedback.startsWith("ทดสอบไม่สำเร็จ") || feedback.includes("ไม่ได้") ? "bg-rose-50 text-rose-700" : "bg-emerald-50 text-emerald-700")}>{feedback}</div>}
      <div className="flex flex-col-reverse gap-2 sm:flex-row sm:justify-end"><Button type="button" variant="outline" disabled={!canTest || testMutation.isPending} onClick={() => { setFeedback(null); testMutation.mutate(); }} className="h-11 rounded-xl sm:min-w-36">{testMutation.isPending ? "กำลังทดสอบ..." : "ส่งข้อความทดสอบ"}</Button><Button type="submit" disabled={saveMutation.isPending} className="h-11 rounded-xl bg-[#0e6b62] px-5 hover:bg-[#09554e]">{saveMutation.isPending ? "กำลังบันทึก..." : "บันทึกการตั้งค่า"}</Button></div>
    </form></CardContent></Card>
    <Card className="rounded-2xl border-slate-200/80 bg-white/85 shadow-sm"><CardHeader className="pb-3"><CardTitle className="text-base">สถานะการเชื่อมต่อ</CardTitle></CardHeader><CardContent className="space-y-4"><StatusItem label="การตั้งค่า" value={settings?.configured ? "พร้อมใช้งาน" : "รอข้อมูลเชื่อมต่อ"} good={Boolean(settings?.configured)} /><StatusItem label="การส่งครั้งล่าสุด" value={settings?.lastDeliveryStatus === "SENT" ? "ส่งสำเร็จ" : settings?.lastDeliveryStatus === "FAILED" ? "ส่งไม่สำเร็จ" : "ยังไม่มีประวัติ"} good={settings?.lastDeliveryStatus === "SENT"} /><div className="rounded-xl bg-slate-50 p-4 text-xs leading-5 text-slate-500"><p className="font-semibold text-slate-700">แนวทางใช้งาน</p><ol className="mt-2 list-decimal space-y-1 pl-4"><li>เพิ่ม Official Account เป็นเพื่อนกับผู้รับ หรือเชิญเข้ากลุ่ม</li><li>นำ token และ ID จาก LINE Developers มาวางในแบบฟอร์ม</li><li>บันทึกแล้วส่งข้อความทดสอบก่อนเปิดใช้งานจริง</li></ol></div>{settings?.lastError && <div className="rounded-xl border border-rose-100 bg-rose-50 p-4 text-xs leading-5 text-rose-700"><b>ข้อผิดพลาดล่าสุด:</b> {settings.lastError}</div>}</CardContent></Card>
  </div>;
}

function ToggleRow({ label, description, checked, onChange }: { label: string; description: string; checked: boolean; onChange: (value: boolean) => void }) { return <label className="flex cursor-pointer items-start justify-between gap-4"><span><span className="block text-sm font-medium text-slate-700">{label}</span><span className="mt-1 block text-xs leading-5 text-slate-500">{description}</span></span><input type="checkbox" checked={checked} onChange={event => onChange(event.target.checked)} className="mt-1 h-5 w-5 shrink-0 accent-[#0e6b62]" /></label>; }
function StatusItem({ label, value, good }: { label: string; value: string; good: boolean }) { return <div className="flex items-center justify-between gap-3 border-b border-slate-100 pb-3"><span className="text-sm text-slate-500">{label}</span><span className={cn("rounded-full px-2.5 py-1 text-xs font-semibold", good ? "bg-emerald-50 text-emerald-700" : "bg-amber-50 text-amber-700")}>{value}</span></div>; }

function AuthShell({ children }: { children: React.ReactNode }) {
  return <div className="flex min-h-screen items-center justify-center bg-[radial-gradient(circle_at_top_right,_rgba(14,107,98,0.16),_transparent_34%),linear-gradient(135deg,_#eef7f5_0%,_#f8fafc_48%,_#f4efe5_100%)] px-4 py-8"><main className="w-full max-w-md rounded-3xl border border-white/70 bg-white/90 p-6 shadow-xl shadow-teal-950/10 backdrop-blur sm:p-8">{children}</main></div>;
}

function LineLoginScreen() {
  return <AuthShell><div className="flex h-12 w-12 items-center justify-center rounded-2xl bg-[#0e6b62] text-white shadow-lg shadow-teal-900/15"><Wrench className="h-6 w-6" /></div><p className="mt-7 text-[11px] font-bold uppercase tracking-[0.2em] text-teal-700">NORTHSTAR HOTEL</p><h1 className="mt-2 text-2xl font-semibold tracking-tight text-slate-900">ศูนย์งานซ่อมบำรุง</h1><p className="mt-3 text-sm leading-6 text-slate-600">เข้าสู่ระบบด้วยบัญชี LINE เพื่อแจ้งซ่อม ติดตามใบงาน และรับการแจ้งเตือนของคุณ</p><a href={`/api/auth/line/start?returnTo=${encodeURIComponent(`${window.location.pathname}${window.location.search}`)}`} className="mt-7 flex min-h-12 w-full items-center justify-center rounded-xl bg-[#06C755] px-4 text-sm font-semibold text-white shadow-sm transition hover:bg-[#05b64c] active:scale-[0.98]">เข้าสู่ระบบด้วย LINE</a><p className="mt-4 text-center text-xs leading-5 text-slate-400">หากเป็นครั้งแรก ระบบจะขอชื่อและแผนกเพื่อสร้างโปรไฟล์ผู้ใช้งาน</p></AuthShell>;
}

function AuthRecoveryScreen({ onRetry }: { onRetry: () => void }) {
  return <AuthShell><div className="flex h-12 w-12 items-center justify-center rounded-2xl bg-amber-50 text-amber-700"><Clock3 className="h-6 w-6" /></div><p className="mt-7 text-[11px] font-bold uppercase tracking-[0.2em] text-amber-700">ตรวจสอบนานกว่าปกติ</p><h1 className="mt-2 text-2xl font-semibold tracking-tight text-slate-900">ยังไม่สามารถยืนยันการเข้าสู่ระบบ</h1><p className="mt-3 text-sm leading-6 text-slate-600">อาจเกิดจาก session หมดอายุ หรือการเชื่อมต่อถูกขัดจังหวะ คุณสามารถตรวจสอบใหม่หรือเริ่มเข้าสู่ระบบด้วย LINE อีกครั้งได้</p><div className="mt-7 grid gap-2 sm:grid-cols-2"><Button type="button" variant="outline" onClick={onRetry} className="min-h-12 rounded-xl">ลองตรวจสอบใหม่</Button><a href={`/api/auth/line/start?returnTo=${encodeURIComponent(`${window.location.pathname}${window.location.search}`)}`} className="flex min-h-12 items-center justify-center rounded-xl bg-[#06C755] px-4 text-sm font-semibold text-white shadow-sm transition hover:bg-[#05b64c] active:scale-[0.98]">เข้าสู่ระบบด้วย LINE</a></div></AuthShell>;
}

function RegistrationScreen({ defaultName, isPending, error, onSubmit }: { defaultName: string; isPending: boolean; error?: string; onSubmit: (event: React.FormEvent<HTMLFormElement>) => void }) {
  return <AuthShell><div className="flex h-12 w-12 items-center justify-center rounded-2xl bg-teal-50 text-[#0e6b62]"><Users2 className="h-6 w-6" /></div><p className="mt-7 text-[11px] font-bold uppercase tracking-[0.2em] text-teal-700">ลงทะเบียนครั้งแรก</p><h1 className="mt-2 text-2xl font-semibold tracking-tight text-slate-900">ข้อมูลผู้ใช้งาน</h1><p className="mt-3 text-sm leading-6 text-slate-600">กรอกชื่อและเลือกแผนกเพียงครั้งเดียว เพื่อให้ระบบระบุผู้แจ้งในใบงานของคุณได้อย่างถูกต้อง</p><form className="mt-7 space-y-5" onSubmit={onSubmit}><label className="block text-sm font-medium text-slate-700">ชื่อผู้ใช้งาน<Input name="displayName" defaultValue={defaultName} required minLength={2} className="mt-2 h-11 rounded-xl" placeholder="ชื่อ - นามสกุล หรือชื่อที่ใช้ปฏิบัติงาน" /></label><label className="block text-sm font-medium text-slate-700">แผนก<select name="department" required defaultValue="" className="mt-2 h-11 w-full rounded-xl border border-slate-200 bg-white px-3 text-sm outline-none focus:border-teal-500"><option value="" disabled>เลือกแผนก</option><option value="FRONT_OFFICE">แผนกต้อนรับ</option><option value="HOUSEKEEPING">แผนกแม่บ้าน</option><option value="FOOD_AND_BEVERAGE">แผนกอาหารและเครื่องดื่ม</option><option value="ENGINEERING">แผนกช่างและวิศวกรรม</option><option value="SECURITY">แผนกรักษาความปลอดภัย</option><option value="FINANCE">แผนกการเงิน</option><option value="ADMINISTRATION">แผนกบริหาร</option><option value="OTHER">อื่น ๆ</option></select></label>{error && <p className="rounded-xl bg-rose-50 px-4 py-3 text-sm text-rose-700">ไม่สามารถบันทึกข้อมูลได้: {error}</p>}<Button type="submit" disabled={isPending} className="h-11 w-full rounded-xl bg-[#0e6b62] hover:bg-[#09554e]">{isPending ? "กำลังบันทึก..." : "บันทึกและเริ่มใช้งาน"}</Button></form></AuthShell>;
}

function SectionPlaceholder({ section, locations, technicians, onCreate }: { section: string; locations: any[]; technicians: any[]; onCreate: () => void }) { return <Card className="rounded-2xl border-slate-200/70 shadow-sm"><CardContent className="p-8"><div className="flex flex-col items-start justify-between gap-6 md:flex-row"><div><div className="mb-3 flex h-12 w-12 items-center justify-center rounded-2xl bg-teal-50 text-teal-700">{section === "Locations" ? <MapPin /> : section === "Technicians" ? <Wrench /> : <Settings2 />}</div><h3 className="text-xl font-semibold">{section === "Locations" ? "พื้นที่" : section === "Technicians" ? "ช่าง" : "การตั้งค่า"} ศูนย์จัดการ</h3><p className="mt-2 max-w-xl text-sm leading-6 text-slate-500">จัดการข้อมูล {section === "Locations" ? "พื้นที่" : section === "Technicians" ? "ช่าง" : "การตั้งค่า"} จากพื้นที่ปฏิบัติงานเดียว รองรับการต่อยอดด้วยแบบฟอร์ม การทำงานแบบกลุ่ม และสิทธิ์ตามบทบาท</p></div><Button onClick={onCreate} className="rounded-xl bg-[#0e6b62]"><Plus className="mr-2 h-4 w-4" /> เพิ่มรายการ</Button></div><div className="mt-8 grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{(section === "Locations" ? locations : section === "Technicians" ? technicians : [{ label: "ค่ามาตรฐานสถานะ", value: "OPEN · ASSIGNED · IN_PROGRESS · COMPLETED · CLOSED" }, { label: "บทบาทผู้ใช้", value: "GUEST · STAFF · SUPERVISOR · TECH · ADMIN" }, { label: "การรับแจ้งผ่าน QR", value: "พร้อมรับแจ้งตามพื้นที่" }]).slice(0, 6).map((item: any, index: number) => <div key={index} className="rounded-xl border border-slate-100 bg-slate-50/60 p-4"><p className="text-xs font-semibold text-slate-700">{item.areaName ?? item.techName ?? item.label}</p>{section === "Technicians" && <p className="mt-2 text-xs leading-5 text-slate-500"><span className="font-semibold text-slate-700">ทักษะ:</span> {item.skills ?? "ยังไม่ระบุ"}</p>}<p className="mt-2 text-xs leading-5 text-slate-500">{section === "Technicians" ? `${item.teamCode ?? "—"} · ${item.shiftCode ?? "—"} · ${item.currentOpenJobs ?? 0}/${item.maxOpenJobs ?? "—"} งานที่เปิด` : item.areaType ?? item.value}</p>{item.qrCode && <div className="mt-3 flex items-center gap-2 text-[10px] font-semibold text-teal-700"><QrCode className="h-3.5 w-3.5" />{item.qrCode}</div>}</div>)}</div></CardContent></Card>; }
